 sections=[
  S("A crowd, in plain words", "<p>A crowd is a large number of people in one place at the same time. Some crowds share a purpose (a concert audience, pilgrims, commuters); others are just people passing (a busy street). Crowd scientists care about crowds because <b>most of the time they are safe and enjoyable, and occasionally they are deadly</b>, and the difference is usually predictable from numbers.</p><p>We describe a crowd with three linked quantities: <b>density</b> (people per square metre), <b>speed</b> (metres per second) and <b>flow</b> (people passing a line per second).</p>",
    ("A crowd", "people", "Many people sharing one space, often one purpose.", [("Shared space and time", "Everyone is in the same place at once."), ("Usually safe", "Most crowds are friendly and orderly."), ("Three numbers", "Density, speed and flow describe it.")])),
  S("Three phases of every event", "<p>Every event has three phases: <b>ingress</b> (arriving), <b>circulation</b> (moving around inside) and <b>egress</b> (leaving). Each has its own peak. Egress is often the most intense, because everyone leaves at once at the end.</p><p>Crowd safety expert Keith Still built these phases into his DIM-ICE model, which you will meet in module 1.8.</p>",
    ("Event phases", "manage", "Ingress, circulation, egress.", [("Ingress", "Arrivals bunch before the start."), ("Circulation", "Moving inside: concourses, toilets, food."), ("Egress", "Everyone leaves together: often the peak.")])),
  S("A queue is a stock", "<p>Picture a bath. The tap is the arrival rate, the plug hole is the gate's capacity, and the water level is the number of people waiting. If the tap runs faster than the plug drains, the level rises. It keeps rising until arrivals fall below capacity, so <b>the biggest queue comes after the busiest arrival time</b>.</p><div class=\"eq\">change in people waiting = arrivals − departures</div><p>A worked example: 90 people a minute arrive at a gate that passes 70. The queue grows by 20 people every minute.</p>",
    ("Stock and flow", "risk", "Waiting people pile up like water in a bath.", [("Arrivals − capacity", "If positive, the queue grows."), ("Peak comes later", "The queue peaks after arrivals peak."), ("90 in, 70 out", "The queue grows by 20 a minute.")])),
  S("Crowd crushes are not panic", "<p>News reports often say a crowd 'panicked' or 'stampeded'. Research tells a different story. In most deadly incidents, people were packed so tightly that they could not move, breathe or escape: <b>compressive asphyxia</b>. People in danger mostly help each other (Drury, Cocking and Reicher 2009).</p><p>Examples you will meet again: the Hillsborough stadium disaster (1989, 97 deaths), the Love Parade in Duisburg (2010, 21 deaths), the Mina crush during the Hajj (2015, 769 deaths in the official Saudi count; independent counts exceed 2,000) and the Itaewon crowd crush in Seoul (2022, 159 deaths). In each, too many people reached too little space.</p>",
    ("Not panic", "risk", "Density and pressure, not irrational behaviour.", [("Compressive asphyxia", "People cannot breathe when squeezed."), ("People help each other", "Drury and colleagues' research."), ("Same root cause", "Too many people, too little space.")])),
 ],
 callouts=[C(2, "try", "Try it in your head", "<p>A stadium gate passes 60 people a minute. For 30 minutes, 100 people a minute arrive. How many are waiting at the end? <i>(100 − 60) × 30 = 1,200.</i></p>"),
           C(3, "trap", "The word 'stampede'", "<p>'Stampede' suggests animals running wildly and blames the victims. Most crushes happen where people are barely moving. Prefer 'crowd crush' or 'crowd collapse'.</p>")],
 explorer=dict(widget="accum", intro="Arrivals follow a bell curve that peaks 45 minutes after the doors open. Change the peak arrival rate and the gate capacity.", predict="If the gate capacity is a little less than the peak arrival rate, does the queue peak at minute 45, or later?"),
 code=[dict(title="A queue as a stock", lang="python", runnable=True, source="arrivals = [20, 50, 90, 120, 90, 50, 20]   # people per minute, one value per 5 minutes\ncapacity = 70                                  # people per minute through the gate\nqueue = 0\nfor i, a in enumerate(arrivals):\n    queue = max(0, queue + (a - capacity) * 5)   # 5 minutes per step\n    print(f'minute {5*(i+1):3d}: arrivals {a:3d}/min, waiting {queue:5d}')",
   explain="Each step adds (arrivals − capacity) × 5 minutes to the queue, never below zero. Change capacity to 100 and run again.", expected="minute   5: arrivals  20/min, waiting     0\n...\nminute  25: arrivals  90/min, waiting   400\nminute  35: arrivals  20/min, waiting     0")],
 takeaways=["A crowd is described by density, speed and flow.", "Every event has ingress, circulation and egress phases, each with its own peak.", "A waiting crowd is a stock: it grows while arrivals exceed capacity, and peaks after the arrival peak.", "Deadly crowd incidents are about density and pressure, not panic."],
 quiz=[Q("A gate passes 50 people per minute and 80 arrive per minute for 10 minutes. How many are waiting at the end?", ["30", "300", "800", "130"], 1, "(80 − 50) × 10 = 300 people."),
       Q("Which event phase is often the most intense?", ["Ingress", "Circulation", "Egress", "Set-up"], 2, "At the end everyone leaves at once, so egress flows are often the largest."),
       Q("What killed most victims of major crowd crushes?", ["Trampling during a panic", "Compressive asphyxia from very high density", "Heat", "Fire"], 1, "People were squeezed so tightly they could not breathe."),
       Q("The biggest queue usually forms…", ["Before arrivals peak", "Exactly when arrivals peak", "After arrivals peak", "At random"], 2, "The queue keeps growing until arrivals fall below capacity, which is after the peak.")],
 glossary=[G("Crowd", "A large number of people gathered in one place at one time, often sharing a purpose."), G("Ingress", "The arrival phase of an event."), G("Circulation", "Movement within a venue during an event."), G("Egress", "The departure phase of an event, normal or emergency."), G("Compressive asphyxia", "Inability to breathe because the chest is squeezed, the main cause of death in crowd crushes."), G("Stock", "A quantity that accumulates, such as the number of people waiting.")],
 resources=[RS("Drury, Cocking and Reicher (2009): Everyone for themselves?", "https://doi.org/10.1348/014466608X357893", "Evidence that people in emergencies cooperate rather than panic."),
            RS("Still: Introduction to Crowd Science (book site)", "https://www.gkstill.com/Support/Book.html", "The crowd science textbook behind DIM-ICE and RAMP analysis."),
            RS("UK HSE: Managing crowds safely (HSG154)", "https://www.hse.gov.uk/pubns/books/hsg154.htm", "A short official guide to planning for crowds at venues and events.")],
